import '@kerfjs/ui/layout.css';
import '@kerfjs/ui/sidebar.css';
import './navigation-sidebar.css';

import { LucideIcon } from '@kerfjs/ui/lucide-icon';
import { MenuHeader } from '@kerfjs/ui/menu-header';
import { MenuItem } from '@kerfjs/ui/menu-item';
import { Toolbar } from '@kerfjs/ui/toolbar';
import { ToolbarControlGroup } from '@kerfjs/ui/toolbar-control-group';
import { delegate, signal } from 'kerfjs';
import { Folder, Inbox, Plus, Settings, Users } from 'lucide';

export function createNavigationSidebar(root: HTMLElement) {
  const selected = signal('inbox');
  const render = () => <aside class="workspace-sidebar kui-layout">
    <div class="workspace-sidebar__body kui-sidebar kui-scroll-owner kui-pane-body">
      <section class="kui-sidebar-section"><MenuHeader label="Workspace" /><MenuItem action="navigate" itemId="inbox" label="Inbox" icon={<LucideIcon icon={Inbox} name="inbox" />} trailing={<span>12</span>} selected={selected.value === 'inbox'} /><MenuItem action="navigate" itemId="shared" label="Shared with me" icon={<LucideIcon icon={Users} name="users" />} selected={selected.value === 'shared'} /><MenuItem action="navigate" itemId="drafts" label="Drafts without an icon" selected={selected.value === 'drafts'} /></section>
      <section class="kui-sidebar-section"><MenuHeader label="Projects" /><MenuItem action="navigate" itemId="design" label="Design system rollout" icon={<LucideIcon icon={Folder} name="folder" />} selected={selected.value === 'design'} multiline /><MenuItem action="navigate" itemId="archive" label="Archived" disabled title="Available to administrators" /><div class="kui-sidebar-surface"><strong>Quarterly goal</strong><p>Ship accessible navigation patterns to every workspace.</p></div></section>
    </div>
    <footer class="workspace-sidebar__footer"><Toolbar label="Sidebar actions" divider={false} leading={<ToolbarControlGroup appearance="borderless" single><button type="button" aria-label="Add project" data-action="add-project"><LucideIcon icon={Plus} name="plus" /></button></ToolbarControlGroup>} trailing={<ToolbarControlGroup appearance="borderless" single><button type="button" aria-label="Workspace settings" data-action="workspace-settings"><LucideIcon icon={Settings} name="settings" /></button></ToolbarControlGroup>} /></footer>
  </aside>;
  const dispose = delegate(root, 'click', '[data-action]', (_event, element) => { if (element.dataset.action === 'navigate' && element.dataset.itemId) selected.value = element.dataset.itemId; });
  return { render, selected, dispose };
}

