.workspace-sidebar { display: grid; inline-size: min(22rem, 100%); block-size: 100%; min-block-size: 0; grid-template-rows: minmax(0, 1fr) auto; background: var(--kui-color-surface); }
.workspace-sidebar__body { min-block-size: 0; }
.workspace-sidebar__footer { border-block-start: 1px solid var(--kui-color-border); }
.workspace-sidebar__footer .kui-toolbar { min-block-size: auto; }
.workspace-sidebar .kui-sidebar-surface p { margin-block-end: 0; color: var(--kui-color-text-quiet); }
